package io.xeros.solo;
import io.xeros.*;import io.xeros.content.skills.mining.*;import io.xeros.model.collisionmap.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.lang.reflect.*;import java.util.*;
public final class MiningPlayableCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){return AttackDefencePlayableCheck.actor();}static long xp(Player p){return AttackDefencePlayableCheck.xp(p,14);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void tick(int n){SkillsAuditCheck.tick(n);}static void clear(Player p){SkillsAuditCheck.clear(p);}static void give(Player p,int id){ok(p.getItems().addItem(id,1),"Fixture");}
 static void block(Player p,int n){switch(n){case 0:p.getHealth().setCurrentHealth(0);break;case 1:p.isBanking=true;break;case 2:p.isShopping=true;break;case 3:p.teleTimer=2;break;case 4:p.isDead=true;break;}}
 static Player at(WorldObject o){Player p=actor();p.absX=o.x-1;p.absY=o.y;p.heightLevel=o.height;give(p,1275);return p;}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;Field f=io.xeros.content.boosts.Boosts.class.getDeclaredField("boosts");f.setAccessible(true);f.set(null,Collections.emptyList());
  WorldObject iron=CoreRockMiningCheck.nodes().stream().filter(o->CoreRockMining.rock(o.id)==CoreRockMining.Rock.IRON).findFirst().orElseThrow();
  for(int n=0;n<5;n++){Player p=at(iron);block(p,n);ok(!CoreRockMining.start(p,iron.id,iron.x,iron.y,b->b==256?0:b-1),"Blocked mining start "+n);clear(p);p=at(iron);long old=xp(p);ok(CoreRockMining.start(p,iron.id,iron.x,iron.y,b->b==256?0:b-1),"Core start");block(p,n);tick(10);ok(count(p,440)==0&&xp(p)==old&&!p.playerSkilling[14],"Mining callback "+n);clear(p);}
  Player p=actor();p.playerEquipment[0]=1275;ok(Pickaxe.getBestPickaxe(p)==null,"Pickaxe hat slot");p.playerEquipment[0]=-1;p.playerEquipment[3]=1275;ok(Pickaxe.getBestPickaxe(p)!=null,"Weapon pickaxe");p.playerEquipment[3]=-1;give(p,1275);ok(Pickaxe.getBestPickaxe(p)!=null,"Inventory pickaxe");clear(p);
  WorldObject gem=PreciousRockCheck.nodes().stream().filter(o->PreciousRockMining.gem(o.id)).findFirst().orElseThrow();p=at(gem);long old=xp(p);ok(PreciousRockMining.start(p,gem.id,gem.x,gem.y,b->b==256?0:b-1),"Gem start");Region region=p.getRegionProvider().get(gem.x,gem.y);region.removeWorldObject(gem.toGlobalObject());try{tick(10);ok(xp(p)==old&&count(p,1623)==0&&!p.playerSkilling[14],"Removed gem rock granted reward");}finally{region.addWorldObject(gem);}clear(p);
  p=actor();p.setLoginName("skills61mineqa");p.setDisplayName("Skills61mineqa");p.setIndex(1);p.isActive=true;p.saveCharacter=true;PlayerHandler.players[1]=p;p.getPA().addSkillXPMultiplied(37.5,14,true);give(p,440);old=xp(p);ok(PlayerSave.saveGameInstant(p),"Mining save");Player q=actor();q.setLoginName("skills61mineqa");ok(PlayerSave.loadGame(q,"skills61mineqa","IsolatedAudit",true).toString().equals("SUCCESS")&&xp(q)==old&&count(q,440)==1,"Mining save load");PlayerHandler.players[1]=null;clear(p);clear(q);
  System.out.println("MINING_FIVE_START_AND_CALLBACK_INTERACTION_GUARDS_PICKAXE_CORRECT_SLOT_REMOVED_NATIVE_GEM_ROCK_AND_REAL_XP_ORE_SAVE_RELOAD_PASS");System.out.println("MINING_PLAYABLE_V61_PASS");System.exit(0);
 }
}
